THOUGHT: I made an error in my reproduction script. Static methods accessed directly from the class don't need the `__func__` attribute. Let me fix the script:

```bash
cat <<'EOF' > reproduce_issue.py
from monkeytype.tracing import get_func_in_mro

class TestClass:
    @property
    def a_property(self):
        return "test"

    @property
    def a_property_with_setter(self):
        return self._value

    @a_property_with_setter.setter
    def a_property_with_setter(self, value):
        self._value = value

    @staticmethod
    def a_static_method():
        return "static"

# This works fine
static_func = get_func_in_mro(TestClass, TestClass.a_static_method.__code__)
print(f"Static method: {static_func}")  # Should return the function

# This returns None unexpectedly  
prop_func = get_func_in_mro(TestClass, TestClass.a_property.fget.__code__)
print(f"Property: {prop_func}")  # Returns None instead of the getter function

# This also returns None unexpectedly
prop_with_setter_func = get_func_in_mro(TestClass, TestClass.a_property_with_setter.fget.__code__)
print(f"Property with setter: {prop_with_setter_func}")  # Returns None instead of the getter function
EOF
```

