class TestClass:
    @property
    def simple_property(self):
        return "simple"

    @property
    def property_with_setter(self):
        return self._value

    @property_with_setter.setter
    def property_with_setter(self, value):
        self._value = value

    @property
    def property_with_deleter(self):
        return self._other_value

    @property_with_deleter.deleter
    def property_with_deleter(self):
        del self._other_value

    @property
    def property_with_both(self):
        return self._both_value

    @property_with_both.setter
    def property_with_both(self, value):
        self._both_value = value

    @property_with_both.deleter
    def property_with_both(self):
        del self._both_value

    @staticmethod
    def a_static_method():
        return "static"

    @classmethod
    def a_class_method(cls):
        return "class"

    def a_regular_method(self):
        return "regular"

# Test all cases
test_cases = [
    ("Static method", TestClass.a_static_method),
    ("Class method", TestClass.a_class_method.__func__),
    ("Regular method", TestClass.a_regular_method),
    ("Simple property", TestClass.simple_property.fget),
    ("Property with setter", TestClass.property_with_setter.fget),
    ("Property with deleter", TestClass.property_with_deleter.fget),
    ("Property with both", TestClass.property_with_both.fget),
]

all_passed = True
for name, func in test_cases:
    try:
        result = get_func_in_mro(TestClass, func.__code__)
        if result is None:
            print(f"FAIL: {name} returned None")
            all_passed = False
        else:
            print(f"PASS: {name}")
    except Exception as e:
        print(f"ERROR: {name} raised {e}")
        all_passed = False

if all_passed:
    print("\nAll tests passed!")
else:
    print("\nSome tests failed!")
EOF
